// Only honor the 🔄 button / /refresh command from the configured chat
const CHAT_ID = 'REPLACE_WITH_CHAT_ID';

const u = $json;
const cb = u.callback_query;
if (cb && cb.data === 'fgi_refresh' && String(cb.from && cb.from.id) === CHAT_ID) {
  return [{ json: { callbackId: cb.id } }];
}
const msg = u.message;
if (msg && String(msg.chat && msg.chat.id) === CHAT_ID
    && ['/refresh', '/now'].includes(String(msg.text || '').trim())) {
  return [{ json: { callbackId: '' } }];
}
return [];

// Quote list for the daily snapshot (runs once regardless of input)
return [
  { json: { name: 'S&P500',  symbol: '%5EGSPC' } },
  { json: { name: 'Nasdaq',  symbol: '%5EIXIC' } },
  { json: { name: 'HSI',     symbol: '%5EHSI' } },
  { json: { name: 'Bitcoin', symbol: 'BTC-USD' } },
].slice(0, 4);

// US monthly series from FRED (no API key needed)
return [
  { json: { label: 'Interest Rate',     series: 'FEDFUNDS', type: 'level' } },
  { json: { label: 'CPI',               series: 'CPIAUCSL', type: 'yoy'   } },
  { json: { label: 'Unemployment Rate', series: 'UNRATE',   type: 'level' } },
];

// Assemble the Daily Fear & Greed Update message (Telegram HTML).
// Pulls data from the upstream fetch nodes; every line is best-effort
// and renders "n/a" when its source failed.

const esc = (s) => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const commas = (n) => Math.round(n).toLocaleString('en-US');

const items = (name) => { try { return $(name).all(); } catch (e) { return []; } };
const first = (name) => { try { return $(name).first().json; } catch (e) { return null; } };

// ── Fear & Greed score: CNN primary, mirror fallback ──
let score = null;
let sourceName = 'CNN';
const cnn = first('Fetch CNN');
if (cnn && cnn.fear_and_greed && typeof cnn.fear_and_greed.score === 'number') {
  score = Math.round(cnn.fear_and_greed.score);
} else {
  const mirror = first('Fetch Mirror');
  let raw = null;
  if (mirror && mirror.score != null) {
    raw = typeof mirror.score === 'number' ? mirror.score
        : (typeof mirror.score.score === 'number' ? mirror.score.score : null);
  }
  if (raw !== null) { score = Math.round(raw); sourceName = 'feargreedchart.com'; }
}
if (score === null) throw new Error('Could not fetch the Fear & Greed score from CNN or the mirror');

const label = score <= 20 ? 'Extreme Fear' : score <= 40 ? 'Fear'
            : score <= 60 ? 'Neutral' : score <= 80 ? 'Greed' : 'Extreme Greed';

// ── Day-over-day change vs the last scheduled 21:35 send ──
// Baseline lives in workflow static data (persists across prod executions).
const sd = $getWorkflowStaticData('global');
let deltaNote = '';
if (typeof sd.lastScore === 'number') {
  const d = score - sd.lastScore;
  deltaNote = d > 0 ? ` (🟢 +${d})` : d < 0 ? ` (🔴 ${d})` : ' (⚪ 0)';
}
let fromSchedule = false;
try { fromSchedule = $('Daily Schedule').isExecuted === true; } catch (e) {}
if (fromSchedule || typeof sd.lastScore !== 'number') sd.lastScore = score;

// ── SGT timestamp ──
const sgtParts = (d, opts) => Object.fromEntries(
  new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Singapore', hourCycle: 'h23', ...opts })
    .formatToParts(d).map(x => [x.type, x.value]));
const p = sgtParts(new Date(), { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
const sgtDate = `${p.year}-${p.month}-${p.day}`;
const sgtTime = `${p.hour}:${p.minute} SGT`;

// ── Index quotes (Yahoo, 1-day move) ──
const symbols = items('Yahoo Symbols');
const quotes = items('Fetch Quotes');
const quoteLines = symbols.map((s, i) => {
  try {
    const meta = quotes[i].json.chart.result[0].meta;
    const price = meta.regularMarketPrice;
    const prev = meta.regularMarketPreviousClose ?? meta.previousClose ?? meta.chartPreviousClose;
    const pct = ((price - prev) / prev) * 100;
    const dir = pct < 0 ? `🔴 -${Math.abs(pct).toFixed(1)}` : `🟢 +${pct.toFixed(1)}`;
    return `  • ${s.json.name}: ${commas(price)} (${dir}%)`;
  } catch (e) { return `  • ${s.json.name}: n/a`; }
});

// ── US monthly series (FRED CSV) ──
const fredSeries = items('FRED Series');
const fredResp = items('Fetch FRED');
const fredDate = (d) => { const [y, m, day] = d.split('-'); return `${+day}/${+m}/${y}`; };
const fredLines = fredSeries.map((s, i) => {
  try {
    const rows = String(fredResp[i].json.data).split('\n')
      .map(r => r.trim())
      .filter(r => /^\d{4}-\d{2}-\d{2},[0-9.]+$/.test(r))
      .map(r => { const [d, v] = r.split(','); return { d, v: parseFloat(v) }; });
    if (s.json.type === 'yoy') {
      if (rows.length < 14) throw new Error('too few rows');
      const cur = ((rows[rows.length - 1].v / rows[rows.length - 13].v) - 1) * 100;
      const last = ((rows[rows.length - 2].v / rows[rows.length - 14].v) - 1) * 100;
      return `  • ${s.json.label}: ${cur.toFixed(1)}% (last: ${last.toFixed(1)}% (as of ${fredDate(rows[rows.length - 2].d)}))`;
    }
    if (rows.length < 2) throw new Error('too few rows');
    const cur = rows[rows.length - 1];
    const last = rows[rows.length - 2];
    return `  • ${s.json.label}: ${cur.v}% (last: ${last.v}% (as of ${fredDate(last.d)}))`;
  } catch (e) { return `  • ${s.json.label}: n/a`; }
});

// ── Top 3 headlines with publish time in SGT (CNBC RSS) ──
let newsLines = ['      • (news unavailable)'];
try {
  const xml = String(first('Fetch News').data).replace(/[\r\n]/g, '');
  const lines = xml.split('<item>').slice(1, 4).map(part => {
    let t = (part.match(/<title>(.*?)<\/title>/) || [])[1] || '';
    t = t.replace(/<!\[CDATA\[|\]\]>/g, '')
         .replace(/&amp;/g, '&').replace(/&#039;|&apos;/g, "'").replace(/&quot;/g, '"').trim();
    if (!t) return null;
    let when = '';
    const pd = (part.match(/<pubDate>(.*?)<\/pubDate>/) || [])[1];
    if (pd) {
      const dt = new Date(pd);
      if (!isNaN(dt)) {
        const pp = sgtParts(dt, { year: 'numeric', month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' });
        when = ` (${+pp.day}/${+pp.month}/${pp.year} ${pp.hour}:${pp.minute} SGT)`;
      }
    }
    return `      • ${t}${when}`;
  }).filter(Boolean);
  if (lines.length) newsLines = lines;
} catch (e) {}

// ── Assemble (HTML parse mode: escape data, then add tags) ──
const warn = sourceName !== 'CNN' ? ' ⚠️ mirror value, CNN unreachable' : '';
const snapshot = [...quoteLines, ...fredLines, '  • Top 3 breaking news:', ...newsLines].join('\n');

const text = [
  '<b><u>📊 Daily Fear &amp; Greed Update</u></b>',
  '',
  `📈 Fear &amp; Greed Index: ${score} (${label})${deltaNote}${esc(warn)}`,
  `📅 ${sgtDate}, ${sgtTime}`,
  '',
  '📉 Index:',
  esc(snapshot),
].join('\n');

return [{ json: { text, score, label, source: sourceName } }];
